export type Sticker = {
  /** Noto codepoint id, e.g. "1f600" or "1f44d_200d_1f525". */
  codepoint: string;
  /** The emoji as a string, for pickers and text fallback. */
  emoji: string;
  name: string;
  category: StickerCategory;
};

export function emojiFromCodepoint(codepoint: string): string {
  return String.fromCodePoint(...codepoint.split('_').map((h) => parseInt(h, 16)));
}

export const STICKERS: readonly Sticker[] = ROWS.map(([codepoint, name, c]) => ({
  codepoint,
  emoji: emojiFromCodepoint(codepoint),
  name,
  category: STICKER_CATEGORIES[c] ?? 'Symbols',
}));

const NOTO_BASE = 'https://fonts.gstatic.com/s/e/notoemoji/latest';

/** Animated GIF (512px). */
export function notoAnimatedGifUrl(codepoint: string): string {
  return `${NOTO_BASE}/${codepoint}/512.gif`;
}
/** Animated WebP (512px); smaller than the GIF, same frames. */
export function notoAnimatedWebpUrl(codepoint: string): string {
  return `${NOTO_BASE}/${codepoint}/512.webp`;
}
/** Static vector. */
export function notoStaticSvgUrl(codepoint: string): string {
  return `${NOTO_BASE}/${codepoint}/emoji.svg`;
}

export function findSticker(codepoint: string): Sticker | undefined {
  return STICKERS.find((s) => s.codepoint === codepoint);
}

export function searchStickers(query: string, category?: StickerCategory): Sticker[] {
  const q = query.trim().toLowerCase();
  return STICKERS.filter(
    (s) => (!category || s.category === category) && (!q || s.name.includes(q) || s.emoji === q),
  );
}
